/**
 * ui-logic.test.mjs - unit tests for assets/logic.js (run with `node --test`).
 * Sections mirror logic.js: dates, grouping, filtering, search, suggestions, hash.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import * as L from '../assets/logic.js';

/**
 * Fixed sample data (docs/SCHEMA.md format). Deliberately NOT data/changes.json:
 * that file is regenerated by the scheduled update, and tests that read it
 * would start failing (and block the update, which runs the tests first) as
 * soon as the live data changed.
 */
const data = JSON.parse(readFileSync(new URL('./fixtures/changes-sample.json', import.meta.url), 'utf8'));

/**
 * Find a day of the fixture by its identity (date + kind). Several tests used
 * `data.days[0]` before schema v2; the fixture now starts with patch days, so
 * they look the hotfix day up explicitly instead.
 */
const dayOf = (date, kind) => data.days.find((d) => d.date === date && L.dayKind(d) === kind);

/** Small helper to build a change object with sensible defaults. */
const mk = (o) => ({ id: 'x', scope: 'class', category: 'Classes', class: null, spec: null, group: null, text: '', notes: [], subjects: [], ...o });

/* ---------- dates ---------- */
test('relativeDay gives friendly hints', () => {
  const now = new Date('2026-11-15T10:00:00Z');
  assert.equal(L.relativeDay('2026-11-15', now), 'today');
  assert.equal(L.relativeDay('2026-11-14', now), 'yesterday');
  assert.equal(L.relativeDay('2026-11-13', now), '2 days ago');
  assert.equal(L.relativeDay('2026-10-25', now), '3 weeks ago');
  assert.equal(L.relativeDay('garbage', now), '');
});

/* ---------- grouping ---------- */
test('groupChanges: all-classes first, specs nested, general by category/group', () => {
  const day = dayOf('2026-11-13', 'hotfix');
  const g = L.groupChanges(day.changes);
  assert.equal(g.count, 5);
  assert.deepEqual(g.classSections.map((s) => s.label), ['All classes', 'Druid', 'Paladin']);
  assert.equal(g.classSections[1].specs[0].label, 'Restoration');
  assert.equal(g.classSections[2].direct.length, 1);
  assert.deepEqual(g.general.map((c) => c.category), ['Dungeons', 'Items']);
  assert.equal(g.general[0].groups[0].group, 'The Deadmines');
});

test('groupChanges puts ungrouped general lines before grouped ones', () => {
  const g = L.groupChanges([
    mk({ scope: 'general', category: 'Dungeons', group: 'A', text: 'a' }),
    mk({ scope: 'general', category: 'Dungeons', group: null, text: 'b' }),
  ]);
  assert.deepEqual(g.general[0].groups.map((x) => x.group), [null, 'A']);
});

/* ---------- filtering: class ---------- */
test('class filter keeps that class plus "All classes" lines', () => {
  const st = { ...L.defaultState(), cls: 'paladin' };
  const v = L.visibleDays(data, st);
  const ids = v.flatMap((d) => d.changes.map((c) => c.id));
  assert.ok(ids.includes('2026-11-13-000')); // all classes
  assert.ok(ids.includes('2026-11-13-002')); // paladin
  assert.ok(ids.includes('2026-11-11-001')); // paladin retribution (every spec)
  assert.ok(!ids.includes('2026-11-13-001')); // druid
  assert.ok(!ids.includes('2026-11-13-p000')); // druid (patch day)
  assert.ok(ids.includes('2026-11-14-p001')); // general lines are unaffected by the class filter
});

/* ---------- filtering: spec ---------- */
test('spec filter keeps spec lines, class-wide lines and All-classes lines', () => {
  const st = { ...L.defaultState(), cls: 'paladin', spec: 'retribution' };
  const ids = L.visibleDays(data, st).flatMap((d) => d.changes.map((c) => c.id));
  assert.ok(ids.includes('2026-11-11-001')); // retribution
  assert.ok(ids.includes('2026-11-11-000')); // paladin, spec null
  assert.ok(ids.includes('2026-11-13-000')); // all classes
  const holy = L.visibleDays(data, { ...st, spec: 'holy' }).flatMap((d) => d.changes.map((c) => c.id));
  assert.ok(!holy.includes('2026-11-11-001')); // retribution hidden for holy
  assert.ok(holy.includes('2026-11-11-000'));
});

test('specsForClass merges vanilla trees with trees seen in data', () => {
  assert.deepEqual(L.specsForClass(data, 'paladin'), ['holy', 'protection', 'retribution']);
  const extra = { days: [{ changes: [mk({ class: 'mage', spec: 'chronomancy' })] }] };
  assert.deepEqual(L.specsForClass(extra, 'mage'), ['arcane', 'fire', 'frost', 'chronomancy']);
  assert.deepEqual(L.specsForClass(data, ''), []);
});

/* ---------- icons ---------- */
test('iconUrl builds the Wowhead URL and rejects odd names', () => {
  assert.equal(L.iconUrl('inv_mace_13'), 'https://wow.zamimg.com/images/wow/icons/medium/inv_mace_13.jpg');
  assert.equal(L.iconUrl('../evil'), null);
  assert.equal(L.iconUrl(undefined), null);
});

test('glyphKey picks neutral glyphs per general category', () => {
  assert.equal(L.glyphKey(mk({})), 'spark');
  assert.equal(L.glyphKey(mk({ scope: 'general', category: 'Items' })), 'gem');
  assert.equal(L.glyphKey(mk({ scope: 'general', category: 'Quests' })), 'scroll');
  assert.equal(L.glyphKey(mk({ scope: 'general', category: 'Dungeons' })), 'arch');
  assert.equal(L.glyphKey(mk({ scope: 'general', category: 'Zones' })), 'hex');
});

/* ---------- search ---------- */
test('matchesQuery: all words, case-insensitive, over text/notes/subjects/group/category', () => {
  const ch = dayOf('2026-11-13', 'hotfix').changes[2]; // Judgement of Command + dev note
  assert.ok(L.matchesQuery(ch, 'JUDGEMENT melee'));
  assert.ok(L.matchesQuery(ch, 'stay ranged')); // in the note
  assert.ok(!L.matchesQuery(ch, 'judgement fireball'));
  assert.ok(L.matchesQuery(ch, '')); // empty matches all
  const deadmines = dayOf('2026-11-13', 'hotfix').changes[3];
  assert.ok(L.matchesQuery(deadmines, 'deadmines')); // group
  assert.ok(L.matchesQuery(deadmines, 'dungeons sneed')); // category + text
  const item = dayOf('2026-11-13', 'hotfix').changes[4];
  assert.ok(L.matchesQuery(item, 'taran')); // subject name / text
});

test('search combines with class filter via visibleDays', () => {
  const v = L.visibleDays(data, { ...L.defaultState(), cls: 'paladin', q: 'windfury' });
  assert.deepEqual(v.flatMap((d) => d.changes.map((c) => c.id)), ['2026-11-11-001']);
});

test('highlightSegments marks matches and escapes regex characters', () => {
  const segs = L.highlightSegments('Judgement of Command', ['judge', 'cmd', 'command']);
  assert.deepEqual(segs.filter((s) => s.match).map((s) => s.text), ['Judge', 'Command']);
  assert.equal(segs.map((s) => s.text).join(''), 'Judgement of Command');
  assert.deepEqual(L.highlightSegments('a (b)', ['(b']), [{ text: 'a ', match: false }, { text: '(b', match: true }, { text: ')', match: false }]);
  assert.deepEqual(L.highlightSegments('abc', []), [{ text: 'abc', match: false }]);
});

/* ---------- suggestions ---------- */
test('empty query suggests skill names, most frequently changed first', () => {
  const extra = { days: [{ changes: [
    mk({ subjects: [{ name: 'Zeal', type: 'spell', icon: 'z' }] }),
    mk({ subjects: [{ name: 'Zeal', type: 'spell', icon: 'z' }, { name: 'Thing', type: 'item', icon: 't' }] }),
    mk({ subjects: [{ name: 'Alpha', type: 'spell', icon: 'a' }] }),
  ] }] };
  const s = L.buildSuggestions(extra, L.defaultState(), '');
  assert.deepEqual(s.map((x) => [x.name, x.count]), [['Zeal', 2], ['Alpha', 1]]); // items excluded
});

test('suggestions respect the class/spec filter', () => {
  const names = (st) => L.buildSuggestions(data, st, '', 50).map((s) => s.name);
  assert.ok(names(L.defaultState()).includes('Wild Growth'));
  assert.ok(!names({ ...L.defaultState(), cls: 'paladin' }).includes('Wild Growth'));
  assert.ok(!names({ ...L.defaultState(), cls: 'paladin', spec: 'holy' }).includes('Unsealed Fury'));
  assert.ok(names({ ...L.defaultState(), cls: 'paladin', spec: 'retribution' }).includes('Unsealed Fury'));
});

test('typing narrows: prefix matches first, then substring; items allowed', () => {
  const s = L.buildSuggestions(data, L.defaultState(), 'ju').map((x) => x.name);
  assert.deepEqual(s.slice(0, 2).sort(), ['Judgement', 'Judgement of Command']);
  const sub = L.buildSuggestions(data, L.defaultState(), 'command').map((x) => x.name);
  assert.deepEqual(sub, ['Judgement of Command']); // substring match
  assert.equal(L.buildSuggestions(data, L.defaultState(), 'icebreaker')[0].type, 'item');
});

/* ---------- hash state ---------- */
test('encodeHash omits defaults and round-trips', () => {
  assert.equal(L.encodeHash(L.defaultState()), '');
  const st = { cls: 'paladin', spec: 'retribution', q: 'judgement of', cats: [], kind: 'all', hideClasses: false };
  const h = L.encodeHash(st);
  assert.match(h, /^#class=paladin&spec=retribution&q=judgement\+of&cats=none$/); // kind=all is omitted
  assert.deepEqual(L.decodeHash(h), st);
});

test('decodeHash accepts the documented example and rejects junk', () => {
  assert.deepEqual(L.decodeHash('#class=paladin&spec=retribution&q=judgement&general=0'),
    { cls: 'paladin', spec: 'retribution', q: 'judgement', cats: [], kind: 'all', hideClasses: false }); // legacy general=0
  assert.deepEqual(L.decodeHash('#class=notaclass&spec=holy'), L.defaultState()); // spec needs a valid class
  assert.equal(L.decodeHash('#class=mage&spec=<script>').spec, '');
  assert.deepEqual(L.decodeHash(''), L.defaultState());
  assert.equal(L.decodeHash('#q=%E0%A4%A').q.length >= 0, true); // malformed escapes do not throw
});

test('sanitizeSelection guards stored values', () => {
  assert.deepEqual(L.sanitizeSelection('druid', 'feral'), { cls: 'druid', spec: 'feral' });
  assert.deepEqual(L.sanitizeSelection(5, 'x'), { cls: '', spec: '' });
});

/* ---------- day kinds (schema v2) ---------- */
test('dayKind: missing or unknown kind means hotfix', () => {
  const legacy = dayOf('2026-11-11', 'hotfix');
  assert.ok(legacy && !('kind' in legacy)); // fixture proves the default: no kind field at all
  assert.equal(L.dayKind(legacy), 'hotfix');
  assert.equal(L.dayKind({ kind: 'patch' }), 'patch');
  assert.equal(L.dayKind({ kind: 'weird' }), 'hotfix');
  assert.equal(L.dayKind(null), 'hotfix');
});

test('dayKey is date + kind, so same-date patch and hotfix differ and are all unique', () => {
  assert.equal(L.dayKey({ date: '2026-11-13', kind: 'patch' }), '2026-11-13|patch');
  assert.equal(L.dayKey({ date: '2026-11-13' }), '2026-11-13|hotfix');
  const keys = data.days.map(L.dayKey);
  assert.equal(new Set(keys).size, keys.length);
  // Two fixture days share 2026-11-13.
  assert.equal(data.days.filter((d) => d.date === '2026-11-13').length, 2);
});

test('visibleDays keeps same-date days separate, in data order', () => {
  const keys = L.visibleDays(data, L.defaultState()).map((v) => L.dayKey(v.day));
  assert.deepEqual(keys, ['2026-11-15|hotfix', '2026-11-14|patch', '2026-11-13|patch', '2026-11-13|hotfix', '2026-11-11|hotfix']);
});

test('kind filter: hotfix / patch / all', () => {
  const keys = (kind) => L.visibleDays(data, { ...L.defaultState(), kind }).map((v) => L.dayKey(v.day));
  assert.deepEqual(keys('patch'), ['2026-11-14|patch', '2026-11-13|patch']);
  assert.deepEqual(keys('hotfix'), ['2026-11-15|hotfix', '2026-11-13|hotfix', '2026-11-11|hotfix']); // legacy day counts as hotfix
  assert.equal(keys('all').length, 5);
  assert.equal(L.matchesKind({ kind: 'patch' }, 'hotfix'), false);
  assert.equal(L.matchesKind({}, 'hotfix'), true);
});

test('kind filter combines with class, category chips and search', () => {
  const ids = (st) => L.visibleDays(data, { ...L.defaultState(), ...st }).flatMap((v) => v.changes.map((c) => c.id));
  assert.deepEqual(ids({ kind: 'patch', cls: 'druid', cats: [] }), ['2026-11-13-p000']);
  assert.deepEqual(ids({ kind: 'patch', q: 'gnome' }), ['2026-11-14-p002']);
  assert.deepEqual(ids({ kind: 'hotfix', q: 'gnome' }), []); // empty -> UI shows the empty state
  assert.deepEqual(ids({ kind: 'patch', cats: [], cls: 'paladin' }), []);
  // Patch-only categories survive and group like any other General category.
  const patch = L.visibleDays(data, { ...L.defaultState(), kind: 'patch' }).find((v) => v.day.date === '2026-11-14');
  assert.deepEqual(L.groupChanges(patch.changes).general.map((c) => c.category), ['Bugfixes', 'Races']);
});

test('per-day counts follow the visible lines', () => {
  const v = L.visibleDays(data, { ...L.defaultState(), kind: 'patch', cats: [] });
  assert.deepEqual(v.map((d) => [L.dayKey(d.day), L.groupChanges(d.changes).count]), [['2026-11-14|patch', 1], ['2026-11-13|patch', 1]]);
});

test('suggestions respect the kind filter', () => {
  const names = (kind) => L.buildSuggestions(data, { ...L.defaultState(), kind }, '', 50).map((s) => s.name);
  assert.ok(names('patch').includes('Fireball'));
  assert.ok(!names('hotfix').includes('Fireball'));
  assert.ok(names('hotfix').includes('Wild Growth'));
  assert.ok(!names('patch').includes('Wild Growth'));
  assert.ok(names('all').includes('Fireball') && names('all').includes('Wild Growth'));
});

test('kind hash: encode omits all, decode ignores unknown values, round-trips', () => {
  assert.equal(L.encodeHash({ ...L.defaultState(), kind: 'patch' }), '#kind=patch');
  assert.equal(L.encodeHash({ ...L.defaultState(), kind: 'hotfix' }), '#kind=hotfix');
  assert.equal(L.encodeHash({ ...L.defaultState(), kind: 'all' }), '');
  assert.equal(L.encodeHash({ ...L.defaultState(), kind: 'bogus' }), '');
  assert.equal(L.decodeHash('#kind=patch').kind, 'patch');
  assert.equal(L.decodeHash('#kind=nonsense').kind, 'all');
  assert.equal(L.decodeHash('#kind=ALL').kind, 'all');
  assert.equal(L.decodeHash('#class=mage&kind=hotfix&cats=none').kind, 'hotfix');
  const st = { cls: 'mage', spec: 'fire', q: 'fire', cats: ['items', 'quests'], kind: 'patch', hideClasses: false };
  assert.deepEqual(L.decodeHash(L.encodeHash(st)), st);
});

/* ---------- tags (schema v3) and the fallback for old data ---------- */
/** Find a fixture change by id, whatever day it is on. */
const byId = (id) => data.days.flatMap((d) => d.changes).find((c) => c.id === id);

test('effectiveTags returns change.tags unchanged when it is a non-empty array', () => {
  const v3 = byId('2026-11-15-000');
  assert.deepEqual(L.effectiveTags(v3), ['class:shaman', 'class:warrior', 'class:rogue', 'talent']);
  assert.equal(L.effectiveTags(v3), v3.tags); // pass-through, not a copy
});

test('effectiveTags derives class, spec and category tags from the old fields', () => {
  // Old shape: no `tags` field at all (the live data today).
  assert.ok(!('tags' in byId('2026-11-13-001')));
  assert.deepEqual(L.effectiveTags(byId('2026-11-13-001')), ['class:druid', 'spec:druid/restoration']);
  assert.deepEqual(L.effectiveTags(byId('2026-11-13-002')), ['class:paladin']);
  assert.deepEqual(L.effectiveTags(byId('2026-11-13-000')), []); // all-classes line: no tags
  assert.deepEqual(L.effectiveTags(byId('2026-11-13-003')), ['dungeons']);
  assert.deepEqual(L.effectiveTags(byId('2026-11-13-004')), ['items']);
  // An empty `tags` array also falls back to the derivation.
  assert.deepEqual(L.effectiveTags(mk({ scope: 'general', category: 'Quests', tags: [] })), ['quests']);
  assert.deepEqual(L.effectiveTags(null), []);
});

test('categoryOfHeading maps every published heading as specified (case-insensitive)', () => {
  const t = (h) => L.categoryOfHeading(h);
  assert.deepEqual(t('Items'), ['items']);
  assert.deepEqual(t('quests'), ['quests']);
  assert.deepEqual(t('Quests and World'), ['quests', 'world']);
  assert.deepEqual(t('Dungeons'), ['dungeons']);
  assert.deepEqual(t('Raids'), ['dungeons']);
  assert.deepEqual(t('Professions'), ['professions']);
  assert.deepEqual(t('Player versus Player'), ['pvp']);
  for (const h of ['User Interface', 'User Interface and Accessibility', 'Cooldown Manager', 'Gamepad Support']) {
    assert.deepEqual(t(h), ['ui'], h);
  }
  assert.deepEqual(t('World'), ['world']);
  assert.deepEqual(t('Enemies and NPCs'), ['world']);
  assert.deepEqual(t('Races'), ['races']);
  assert.deepEqual(t('Racial Abilities and Traits'), ['races']);
  assert.deepEqual(t('Legacy System'), ['systems']);
  assert.deepEqual(t('Bugfixes'), ['bugfix']);
  assert.deepEqual(t('Bug Fixes'), ['bugfix']);
  for (const h of ['Known Issues – New with this build', 'Known Issues - New to this build', 'New to this build - Known Issues']) {
    assert.deepEqual(t(h), ['known-issue'], h);
  }
  assert.deepEqual(t('Stranglethorn Fishing Extravaganza'), ['events']);
  assert.deepEqual(t('Customer Support'), ['other']);
  assert.deepEqual(t('Changes and Updates'), ['other']);
  assert.deepEqual(t('Classes'), []); // class lines are described by class/spec tags
});

test('classTagsOf / categoryTagsOf split tags; unknown category tags count as "other"', () => {
  const v3 = byId('2026-11-15-000');
  assert.deepEqual(L.classTagsOf(v3), ['shaman', 'warrior', 'rogue']);
  assert.deepEqual(L.categoryTagsOf(v3), []); // talent is not a category
  assert.deepEqual(L.categoryTagsOf(byId('2026-11-15-004')), ['quests', 'world']);
  assert.deepEqual(L.categoryTagsOf(mk({ tags: ['brand-new-tag', 'class:mage'] })), ['other']);
});

test('availableCategories lists only tags present in the data, in chip order', () => {
  assert.deepEqual(L.availableCategories(data).map((c) => c.slug),
    ['items', 'quests', 'dungeons', 'world', 'races', 'bugfix', 'known-issue']);
  assert.deepEqual(L.availableCategories({ days: [] }), []);
  // A line with only a class has no category, so it adds no chip.
  assert.deepEqual(L.availableCategories({ days: [{ changes: [mk({ class: 'mage' })] }] }), []);
});

/* ---------- filter semantics via tags ---------- */
/** Ids visible for a state (all days, all kinds). */
const idsFor = (st) => L.visibleDays(data, { ...L.defaultState(), ...st }).flatMap((v) => v.changes.map((c) => c.id));

test('class filter uses class: tags, so a line matches every class it is tagged with', () => {
  // 2026-11-15-000 is published under Shaman but tagged warrior + rogue too.
  for (const cls of ['shaman', 'warrior', 'rogue']) assert.ok(idsFor({ cls }).includes('2026-11-15-000'), cls);
  assert.ok(!idsFor({ cls: 'paladin' }).includes('2026-11-15-000'));
  // An Items line tagged class:shaman is found under Shaman, not under Paladin.
  assert.ok(idsFor({ cls: 'shaman' }).includes('2026-11-15-001'));
  assert.ok(!idsFor({ cls: 'paladin' }).includes('2026-11-15-001'));
  // All-class lines (no class tag, no category tag) pass every class filter.
  assert.ok(idsFor({ cls: 'rogue' }).includes('2026-11-13-000'));
});

test('tree filter: spec: tag, or class tag without any spec: tag of that class', () => {
  const ret = idsFor({ cls: 'paladin', spec: 'retribution' });
  assert.ok(ret.includes('2026-11-15-002')); // tagged spec:paladin/retribution
  assert.ok(ret.includes('2026-11-13-002')); // class:paladin, no spec tag (class-wide)
  assert.ok(ret.includes('2026-11-13-000')); // all-class
  assert.ok(!idsFor({ cls: 'paladin', spec: 'holy' }).includes('2026-11-15-002'));
  // Frost line is hidden for Mage > Fire, shown for Mage > Frost.
  assert.ok(!idsFor({ cls: 'mage', spec: 'fire' }).includes('2026-11-15-003'));
  assert.ok(idsFor({ cls: 'mage', spec: 'frost' }).includes('2026-11-15-003'));
  // Multi-class line with no spec tag of the chosen class stays visible under a tree of that class.
  assert.ok(idsFor({ cls: 'warrior', spec: 'arms' }).includes('2026-11-15-000'));
});

test('category chips: a line without class tags shows when one of its categories is on', () => {
  const noClass = (ch) => L.categoryTagsOf(ch).length > 0 && L.classTagsOf(ch).length === 0;
  const onlyQuests = L.visibleDays(data, { ...L.defaultState(), cats: ['quests'] }).flatMap((v) => v.changes).filter(noClass);
  assert.deepEqual(onlyQuests.map((c) => c.id), ['2026-11-15-004', '2026-11-11-002']);
  // quests+world line is visible with only "world" on.
  assert.ok(idsFor({ cats: ['world'] }).includes('2026-11-15-004'));
  assert.ok(!idsFor({ cats: ['items'] }).includes('2026-11-15-004'));
  // Old-shape general line (derived tag) follows its chip too.
  assert.ok(idsFor({ cats: ['dungeons'] }).includes('2026-11-13-003'));
  assert.ok(!idsFor({ cats: ['items'] }).includes('2026-11-13-003'));
});

test('category chips never hide class-tagged lines or all-class lines', () => {
  const none = idsFor({ cats: [] });
  assert.ok(none.includes('2026-11-15-000')); // class-tagged
  assert.ok(none.includes('2026-11-15-001')); // an Items line tagged class:shaman
  assert.ok(none.includes('2026-11-13-000')); // all-class line
  assert.ok(!none.includes('2026-11-13-004')); // plain Items line: hidden
  assert.ok(none.every((id) => !['2026-11-14-p001', '2026-11-15-005'].includes(id))); // bug fix / known issue hidden
  // With a class chosen, non-class lines still follow the chips (old General behaviour).
  assert.ok(idsFor({ cls: 'druid' }).includes('2026-11-13-004'));
  assert.ok(!idsFor({ cls: 'druid', cats: [] }).includes('2026-11-13-004'));
});

test('default state shows every change; cats null means all on', () => {
  const total = data.days.reduce((n, d) => n + d.changes.length, 0);
  assert.equal(idsFor({}).length, total);
  assert.equal(L.isCategoryOn(L.defaultState(), 'anything'), true);
  assert.equal(L.isCategoryOn({ cats: ['items'] }, 'items'), true);
  assert.equal(L.isCategoryOn({ cats: ['items'] }, 'quests'), false);
});

test('toggleCategory / normalizeCats keep one canonical form', () => {
  const avail = L.availableCategories(data); // items, quests, dungeons, world, races, bugfix, known-issue
  const all = avail.map((c) => c.slug);
  assert.equal(L.normalizeCats(all, avail), null);
  assert.equal(L.normalizeCats(null, avail), null);
  assert.deepEqual(L.normalizeCats(['races', 'items'], avail), ['items', 'races']); // chip order
  const off = L.toggleCategory(null, 'quests', avail); // first click turns one off
  assert.deepEqual(off, all.filter((s) => s !== 'quests'));
  assert.equal(L.toggleCategory(off, 'quests', avail), null); // turning it back on = all on again
  assert.deepEqual(L.toggleCategory([], 'items', avail), ['items']);
});

test('suggestions respect the category chips', () => {
  const extra = { days: [{ changes: [
    mk({ scope: 'general', category: 'Items', subjects: [{ name: 'Gizmo', type: 'item', icon: 'g' }] }),
    mk({ scope: 'general', category: 'Quests', subjects: [{ name: 'Quillboar', type: 'item', icon: 'q' }] }),
  ] }] };
  const names = (cats) => L.buildSuggestions(extra, { ...L.defaultState(), cats }, 'g', 50).map((s) => s.name);
  assert.deepEqual(names(null), ['Gizmo']);
  assert.deepEqual(L.buildSuggestions(extra, { ...L.defaultState(), cats: ['quests'] }, 'g', 50).map((s) => s.name), []);
  assert.deepEqual(L.buildSuggestions(extra, { ...L.defaultState(), cats: ['quests'] }, 'quill', 50).map((s) => s.name), ['Quillboar']);
});

/* ---------- hash: category chips ---------- */
test('cats hash: only enabled categories, none, and general=0 compatibility', () => {
  assert.equal(L.encodeHash({ ...L.defaultState(), cats: ['quests', 'items'] }), '#cats=items,quests');
  assert.equal(L.encodeHash({ ...L.defaultState(), cats: [] }), '#cats=none');
  assert.equal(L.encodeHash({ ...L.defaultState(), cats: null }), '');
  assert.equal(L.encodeHash({ ...L.defaultState(), cls: 'mage', cats: ['pvp'] }), '#class=mage&cats=pvp');
  assert.deepEqual(L.decodeHash('#cats=items,quests').cats, ['items', 'quests']);
  assert.deepEqual(L.decodeHash('#cats=none').cats, []);
  assert.equal(L.decodeHash('#cats=bogus').cats, null); // junk -> all on
  assert.deepEqual(L.decodeHash('#cats=quests,bogus').cats, ['quests']);
  assert.deepEqual(L.decodeHash('#general=0').cats, []); // legacy
  assert.equal(L.decodeHash('#general=1').cats, null);
  assert.deepEqual(L.decodeHash('#general=0&cats=items').cats, ['items']); // cats wins
  const st = { cls: 'rogue', spec: '', q: 'x', cats: ['ui', 'world'], kind: 'hotfix', hideClasses: false };
  assert.deepEqual(L.decodeHash(L.encodeHash(st)), st);
});

/* ---------- compact headings ---------- */
/** Headings of a card as "A › B" strings, for readable assertions. */
const headingTitles = (card) => card.headings.map((h) => h.title.join(' › '));

test('flattenSections: a class with one tree has ONE heading "Druid › Restoration"', () => {
  const f = L.flattenSections(dayOf('2026-11-13', 'hotfix').changes);
  assert.equal(f.count, 5);
  const druid = f.cards.find((c) => c.class === 'druid');
  assert.deepEqual(headingTitles(druid), ['Druid › Restoration']);
  assert.equal(druid.headings[0].changes.length, 1);
});

test('flattenSections: class-wide and tree lines become sibling headings', () => {
  const f = L.flattenSections([
    mk({ id: 'a', class: 'paladin', text: 'wide' }),
    mk({ id: 'b', class: 'paladin', spec: 'retribution', text: 'tree' }),
    mk({ id: 'c', class: 'paladin', spec: 'holy', text: 'tree2' }),
  ]);
  assert.equal(f.cards.length, 1); // one card per class
  assert.deepEqual(headingTitles(f.cards[0]), ['Paladin', 'Paladin › Holy', 'Paladin › Retribution']);
  assert.deepEqual(f.cards[0].headings.map((h) => h.spec), [null, 'holy', 'retribution']);
});

test('flattenSections: all-classes first, classes alphabetical, then general categories', () => {
  const f = L.flattenSections(dayOf('2026-11-13', 'hotfix').changes);
  assert.deepEqual(f.cards.map((c) => c.kind === 'class' ? (c.class || 'all') : c.category), ['all', 'druid', 'paladin', 'Dungeons', 'Items']);
  assert.deepEqual(headingTitles(f.cards[0]), ['All classes']);
});

test('flattenSections: general group is inline in the heading, no separate "General"', () => {
  const f = L.flattenSections([
    mk({ scope: 'general', category: 'Dungeons', group: 'The Deadmines', text: 'a' }),
    mk({ scope: 'general', category: 'Dungeons', group: null, text: 'b' }),
    mk({ scope: 'general', category: 'Professions', group: 'Tailoring', text: 'c' }),
  ]);
  assert.deepEqual(f.cards.map(headingTitles), [['Dungeons', 'Dungeons › The Deadmines'], ['Professions › Tailoring']]);
  assert.ok(f.cards.flatMap(headingTitles).every((t) => !/general/i.test(t)));
  assert.equal(f.cards[0].headings[1].group, 'The Deadmines');
});

test('flattenSections keeps each line once, in its published section (multi-class line)', () => {
  const f = L.flattenSections(dayOf('2026-11-15', 'hotfix').changes);
  const places = f.cards.flatMap((c) => c.headings.flatMap((h) => h.changes.map((ch) => [ch.id, headingTitles({ headings: [h] })[0]])));
  assert.equal(places.filter(([id]) => id === '2026-11-15-000').length, 1);
  assert.deepEqual(places.find(([id]) => id === '2026-11-15-000'), ['2026-11-15-000', 'Shaman']);
  assert.deepEqual(places.find(([id]) => id === '2026-11-15-001'), ['2026-11-15-001', 'Items']); // Items line tagged class:shaman stays under Items
  assert.equal(places.length, f.count);
});

/* ---------- extra tags and icon cluster ---------- */
test('extraTagsForLine: other classes, Talent and other categories, never the section itself', () => {
  const multi = L.extraTagsForLine(byId('2026-11-15-000')); // published under Shaman
  assert.deepEqual(multi.map((t) => `${t.type}:${t.slug || ''}`), ['class:warrior', 'class:rogue', 'talent:']);
  assert.equal(multi[0].label, 'Warrior');
  assert.equal(multi[0].color, '#C69B6D');
  // Items line tagged class:shaman: the class is extra, "items" is the section's own category.
  assert.deepEqual(L.extraTagsForLine(byId('2026-11-15-001')).map((t) => t.type + ':' + t.slug), ['class:shaman']);
  // "Quests and World" owns quests AND world: nothing extra.
  assert.deepEqual(L.extraTagsForLine(byId('2026-11-15-004')), []);
  // A class line that is also about quests gets a category chip; its own class and spec are omitted.
  assert.deepEqual(L.extraTagsForLine(byId('2026-11-15-006')).map((t) => t.type + ':' + t.slug), ['category:quests']);
  // Spec tag only -> nothing; old-shape lines have nothing extra.
  assert.deepEqual(L.extraTagsForLine(byId('2026-11-13-001')), []);
  assert.deepEqual(L.extraTagsForLine(byId('2026-11-13-003')), []);
  assert.deepEqual(L.extraTagsForLine(byId('2026-11-15-002')).map((t) => t.type), ['talent']);
});

test('iconSlots caps at 4 icons, marks talents in the title, keeps the rest as overflow', () => {
  const five = L.iconSlots(byId('2026-11-15-003'));
  assert.equal(five.slots.length, 4);
  assert.deepEqual(five.slots.map((s) => s.name), ['Frost Nova', 'Cone of Cold', 'Frostbolt', 'Ice Barrier']);
  assert.deepEqual(five.more.map((s) => s.name), ['Blizzard']);
  assert.deepEqual(five.slots.map((s) => s.talent), [false, false, false, true]);
  assert.equal(five.slots[3].title, 'Ice Barrier (talent)');
  assert.equal(five.slots[0].title, 'Frost Nova');
  const three = L.iconSlots(byId('2026-11-15-000'));
  assert.deepEqual(three.slots.map((s) => s.title), ['Windfury Totem', 'Whirlwind', 'Mutilate (talent)']);
  assert.equal(three.more.length, 0);
  // Old-shape subjects (no kind) are plain; no subjects -> no slots (UI shows one fallback tile).
  assert.equal(L.iconSlots(byId('2026-11-13-002')).slots.length, 1);
  assert.deepEqual(L.iconSlots(byId('2026-11-13-004')).slots.map((s) => s.talent), [false]);
  assert.deepEqual(L.iconSlots(mk({})), { slots: [], more: [] });
  assert.equal(L.iconSlots(byId('2026-11-15-003'), 2).more.length, 3);
});

test('subjectTitle: talent kind, optional tree, quiet unverified hint', () => {
  assert.equal(L.subjectTitle({ name: 'Fireball', kind: 'ability' }), 'Fireball');
  assert.equal(L.subjectTitle({ name: 'Fireball' }), 'Fireball'); // old data: no kind
  assert.equal(L.subjectTitle({ name: 'Oath of Light', kind: 'talent' }), 'Oath of Light (talent)');
  assert.equal(L.subjectTitle({ name: 'Oath of Light', kind: 'talent', tree: 'holy' }), 'Oath of Light (Holy talent)');
  assert.equal(L.subjectTitle({ name: 'Aimed Shot', kind: 'talent', tree: 'beast-mastery' }), 'Aimed Shot (Beast Mastery talent)');
  assert.equal(L.subjectTitle({ name: 'X', verified: true }), 'X'); // verified: nothing extra
  assert.equal(L.subjectTitle({ name: 'X', verified: false }), 'X – unverified icon');
  assert.equal(L.subjectTitle({ name: 'Oath of Light', kind: 'talent', tree: 'holy', verified: false }), 'Oath of Light (Holy talent) – unverified icon');
  assert.equal(L.iconSlots(mk({ subjects: [{ name: 'Oath', kind: 'talent', tree: 'holy', icon: 'a' }] })).slots[0].title, 'Oath (Holy talent)');
});

/* ---------- mobile filter panel helpers ---------- */
test('activeFilterCount counts class, tree, kind and categories (not the search text)', () => {
  assert.equal(L.activeFilterCount(L.defaultState()), 0);
  assert.equal(L.activeFilterCount({ ...L.defaultState(), q: 'fire' }), 0);
  assert.equal(L.activeFilterCount({ ...L.defaultState(), cls: 'mage' }), 1);
  assert.equal(L.activeFilterCount({ ...L.defaultState(), cls: 'mage', spec: 'fire' }), 2);
  assert.equal(L.activeFilterCount({ cls: 'mage', spec: 'fire', q: '', kind: 'patch', cats: [] }), 4);
  assert.equal(L.activeFilterCount({ ...L.defaultState(), kind: 'bogus' }), 0);
});

test('filterSummary: empty when unfiltered, otherwise a compact one-liner', () => {
  assert.equal(L.filterSummary(L.defaultState()), '');
  assert.equal(L.filterSummary({ ...L.defaultState(), q: 'x' }), '');
  assert.equal(L.filterSummary({ cls: 'paladin', spec: 'retribution', q: '', kind: 'patch', cats: ['items', 'quests', 'pvp'] }),
    'Paladin › Retribution · Patches · 3 categories');
  assert.equal(L.filterSummary({ ...L.defaultState(), cls: 'druid' }), 'Druid');
  assert.equal(L.filterSummary({ ...L.defaultState(), kind: 'hotfix', cats: ['items'] }), 'Hotfixes · Items');
  assert.equal(L.filterSummary({ ...L.defaultState(), cats: [] }), 'No categories');
  assert.equal(L.filterSummary({ ...L.defaultState(), cls: 'hunter', spec: 'beast-mastery' }), 'Hunter › Beast Mastery');
});

test('panel flag: filters=open is read and written, and ignored by decodeHash', () => {
  assert.equal(L.hasPanelFlag('#filters=open'), true);
  assert.equal(L.hasPanelFlag('#class=mage&filters=open'), true);
  assert.equal(L.hasPanelFlag('#class=mage'), false);
  assert.equal(L.hasPanelFlag(''), false);
  assert.equal(L.withPanelFlag('', true), '#filters=open');
  assert.equal(L.withPanelFlag('#class=mage', true), '#class=mage&filters=open');
  assert.equal(L.withPanelFlag('#class=mage', false), '#class=mage');
  assert.deepEqual(L.decodeHash('#class=mage&filters=open'), { ...L.defaultState(), cls: 'mage' });
});

/* ---------- subject aliases (SCHEMA v3 addendum) ---------- */
test('alias: included in the icon title, and the label shows "Name (Alias)"', () => {
  assert.equal(L.subjectTitle({ name: 'Unsealed Fury', alias: 'Unsealed Wrath', kind: 'talent', tree: 'retribution' }),
    'Unsealed Fury (in game: Unsealed Wrath, Retribution talent)');
  assert.equal(L.subjectTitle({ name: 'Fireball', alias: 'Pyroblast Lite' }), 'Fireball (in game: Pyroblast Lite)');
  assert.equal(L.subjectTitle({ name: 'Fireball', alias: 'Fireball' }), 'Fireball'); // same name: no noise
  assert.equal(L.subjectLabel({ name: 'Unsealed Fury', alias: 'Unsealed Wrath' }), 'Unsealed Fury (Unsealed Wrath)');
  assert.equal(L.subjectLabel({ name: 'Fireball' }), 'Fireball');
  // Fixture subject: alias + unverified icon.
  const seal = L.iconSlots(byId('2026-11-15-002')).slots[1];
  assert.equal(seal.title, 'Seal of Fury (in game: Seal of Wrath) – unverified icon');
});

test('alias: searching for either name finds the line, and the suggestion shows both', () => {
  const ch = byId('2026-11-15-002');
  assert.ok(L.matchesQuery(ch, 'seal of fury'));
  assert.ok(L.matchesQuery(ch, 'seal of wrath')); // alias only appears in the subject, not the text
  assert.ok(!/wrath/i.test(ch.text));
  assert.deepEqual(idsFor({ q: 'seal of wrath' }), ['2026-11-15-002']);
  for (const q of ['seal of f', 'wrath']) {
    const hit = L.buildSuggestions(data, L.defaultState(), q, 50).find((s) => s.name === 'Seal of Fury');
    assert.ok(hit, q);
    assert.equal(hit.label, 'Seal of Fury (Seal of Wrath)');
    assert.equal(hit.alias, 'Seal of Wrath');
  }
  // Prefix on the alias ranks as a prefix match.
  assert.equal(L.buildSuggestions(data, L.defaultState(), 'seal of w', 50)[0].name, 'Seal of Fury');
  // Subjects without alias keep a plain label.
  assert.equal(L.buildSuggestions(data, L.defaultState(), 'Fireball', 5)[0].label, 'Fireball');
});

/* ---------- hiding class changes ("No classes", class=none) ---------- */
/** State with class changes hidden, plus overrides. */
const hidden = (st = {}) => ({ ...L.defaultState(), hideClasses: true, ...st });
/** Every fixture change, flat. */
const allChanges = () => data.days.flatMap((d) => d.changes);

test('isClassChange: published under Classes, whatever the tags say', () => {
  assert.equal(L.isClassChange(byId('2026-11-13-002')), true); // Paladin heading
  assert.equal(L.isClassChange(byId('2026-11-13-001')), true); // Druid › Restoration
  assert.equal(L.isClassChange(byId('2026-11-13-000')), true); // all-class line, no tags
  assert.equal(L.isClassChange(byId('2026-11-15-007')), true); // all-class line tagged bugfix only
  assert.equal(L.isClassChange(byId('2026-11-15-006')), true); // Druid line also tagged quests
  assert.equal(L.isClassChange(byId('2026-11-15-001')), false); // Items line tagged class:shaman
  assert.equal(L.isClassChange(byId('2026-11-13-004')), false); // plain Items line
  assert.equal(L.isClassChange(null), false);
});

test('classChoice / withClassChoice: all, none or one class, mutually exclusive', () => {
  assert.equal(L.classChoice(L.defaultState()), 'all');
  assert.equal(L.classChoice(hidden()), 'none');
  assert.equal(L.classChoice({ ...L.defaultState(), cls: 'mage' }), 'mage');
  assert.equal(L.classChoice({ cls: 'mage', hideClasses: true }), 'mage'); // a class wins
  const ret = { ...L.defaultState(), cls: 'paladin', spec: 'retribution', q: 'x', kind: 'patch', cats: ['items'] };
  // Hiding clears the class and tree but keeps search, kind and categories.
  assert.deepEqual(L.withClassChoice(ret, 'none'), { ...ret, cls: '', spec: '', hideClasses: true });
  // A class or "All classes" turns the hiding off.
  assert.deepEqual(L.withClassChoice(hidden(), 'druid'), { ...L.defaultState(), cls: 'druid' });
  assert.deepEqual(L.withClassChoice(hidden(), 'all'), L.defaultState());
  assert.deepEqual(L.withClassChoice(hidden(), 'not-a-class'), L.defaultState());
});

test('normalizeClassState: a class turns hiding off; no class means no tree', () => {
  assert.deepEqual(L.normalizeClassState({ ...L.defaultState(), cls: 'rogue', hideClasses: true }), { ...L.defaultState(), cls: 'rogue' });
  assert.deepEqual(L.normalizeClassState({ ...L.defaultState(), spec: 'arms', hideClasses: true }), hidden());
  const legacy = { cls: '', spec: '', q: '', cats: null, kind: 'all' }; // no hideClasses field at all
  assert.deepEqual(L.normalizeClassState(legacy), L.defaultState());
});

test('No classes: every class change is hidden, every non-class line follows the chips', () => {
  const ids = idsFor(hidden());
  const expected = allChanges().filter((c) => c.scope === 'general').map((c) => c.id);
  assert.deepEqual(ids, expected); // all categories on: exactly the non-class lines
  assert.ok(!ids.includes('2026-11-13-000')); // all-class line
  assert.ok(!ids.includes('2026-11-15-007')); // all-class line with a bugfix tag
  assert.ok(!ids.includes('2026-11-15-000')); // multi-class line
});

test('No classes: a class line with a category tag stays hidden even with that category on', () => {
  assert.deepEqual(L.categoryTagsOf(byId('2026-11-15-006')), ['quests']);
  assert.ok(!idsFor(hidden({ cats: ['quests'] })).includes('2026-11-15-006'));
  assert.ok(!idsFor(hidden({ cats: ['bugfix'] })).includes('2026-11-15-007'));
  // Without hiding, the same quests-only view still shows it (class-tagged lines ignore the chips).
  assert.ok(idsFor({ cats: ['quests'] }).includes('2026-11-15-006'));
});

test('No classes: an Items line tagged class:shaman is not a class change and follows the Items chip', () => {
  assert.ok(idsFor(hidden()).includes('2026-11-15-001'));
  assert.ok(idsFor(hidden({ cats: ['items'] })).includes('2026-11-15-001'));
  // Its class tag no longer exempts it from the chips once classes are hidden.
  assert.ok(!idsFor(hidden({ cats: ['quests'] })).includes('2026-11-15-001'));
  assert.ok(idsFor({ cats: ['quests'] }).includes('2026-11-15-001')); // unchanged when not hiding
});

test('No classes: no class cards, no empty day blocks, per-day counts match the lines', () => {
  const days = L.visibleDays(data, hidden());
  assert.ok(days.length > 0);
  for (const { day, changes } of days) {
    const view = L.flattenSections(changes);
    assert.equal(view.cards.filter((c) => c.kind === 'class').length, 0, L.dayKey(day));
    assert.ok(view.cards.length > 0 && view.cards.every((c) => c.headings.every((h) => h.changes.length > 0)));
    assert.equal(view.count, day.changes.filter((c) => c.scope === 'general').length, L.dayKey(day));
  }
  // The 2026-11-11 hotfix day keeps only its Quests line; a day with only class lines would vanish.
  const nov11 = days.find((d) => L.dayKey(d.day) === '2026-11-11|hotfix');
  assert.deepEqual(nov11.changes.map((c) => c.id), ['2026-11-11-002']);
});

test('No classes combines with kind, categories and search', () => {
  assert.deepEqual(idsFor(hidden({ kind: 'patch' })), ['2026-11-14-p001', '2026-11-14-p002', '2026-11-14-p003', '2026-11-13-p001']);
  assert.deepEqual(idsFor(hidden({ kind: 'patch', cats: ['races'] })), ['2026-11-14-p002', '2026-11-14-p003']);
  assert.deepEqual(idsFor(hidden({ q: 'windfury' })), []); // only class lines mention it
  assert.deepEqual(idsFor(hidden({ q: 'sneed' })), ['2026-11-13-003']);
});

test('No classes: suggestions drop skills that only class lines mention', () => {
  const names = (st, q = '') => L.buildSuggestions(data, st, q, 50).map((s) => s.name);
  for (const skill of ['Wild Growth', 'Fireball', 'Judgement', 'Dazed', 'Windfury Totem']) {
    assert.ok(names(L.defaultState()).includes(skill), skill);
    assert.ok(!names(hidden()).includes(skill), skill);
  }
  // Non-class subjects are still offered while typing.
  assert.deepEqual(names(hidden(), 'storm'), ['Stormcaller’s Hauberk']);
  assert.deepEqual(names(hidden({ cats: ['quests'] }), 'storm'), []);
});

test('class=none hash: encode, decode, round-trip, junk ignored', () => {
  assert.equal(L.encodeHash(hidden()), '#class=none');
  assert.equal(L.encodeHash(hidden({ spec: 'holy' })), '#class=none'); // no tree without a class
  assert.equal(L.encodeHash(hidden({ kind: 'patch', cats: ['items'] })), '#class=none&kind=patch&cats=items');
  assert.equal(L.encodeHash({ ...L.defaultState(), cls: 'mage', hideClasses: true }), '#class=mage'); // class wins
  assert.deepEqual(L.decodeHash('#class=none'), hidden());
  assert.deepEqual(L.decodeHash('#class=none&spec=holy'), hidden()); // spec dropped
  assert.deepEqual(L.decodeHash('#class=none&cats=none'), hidden({ cats: [] }));
  assert.deepEqual(L.decodeHash('#class=NONE'), L.defaultState()); // like class slugs: exact lower case
  assert.deepEqual(L.decodeHash('#class=nobody'), L.defaultState());
  assert.equal(L.decodeHash('#class=paladin').hideClasses, false);
  for (const st of [hidden(), hidden({ q: 'sneed', kind: 'hotfix', cats: ['items', 'dungeons'] }), hidden({ cats: [] })]) {
    assert.deepEqual(L.decodeHash(L.encodeHash(st)), st);
  }
  assert.deepEqual(L.decodeHash('#class=none&filters=open'), hidden()); // UI flag ignored
});

test('sanitizeStoredSelection restores a class or the hiding, nothing else', () => {
  assert.deepEqual(L.sanitizeStoredSelection({ cls: 'paladin', spec: 'holy' }), { cls: 'paladin', spec: 'holy', hideClasses: false });
  assert.deepEqual(L.sanitizeStoredSelection({ cls: '', spec: '', hideClasses: true }), { cls: '', spec: '', hideClasses: true });
  assert.deepEqual(L.sanitizeStoredSelection({ cls: 'mage', hideClasses: true }), { cls: 'mage', spec: '', hideClasses: false });
  assert.equal(L.sanitizeStoredSelection({ cls: '', spec: '' }), null); // "All classes": nothing to restore
  assert.equal(L.sanitizeStoredSelection({ hideClasses: 'yes' }), null);
  assert.equal(L.sanitizeStoredSelection(null), null);
  assert.equal(L.sanitizeStoredSelection('paladin'), null);
});

test('No classes counts as one active filter and is named in the summary', () => {
  assert.equal(L.activeFilterCount(hidden()), 1);
  assert.equal(L.activeFilterCount(hidden({ kind: 'patch', cats: [] })), 3);
  assert.equal(L.activeFilterCount(hidden({ spec: 'holy' })), 1); // a stray tree never counts without a class
  assert.equal(L.filterSummary(hidden()), 'No class changes');
  assert.equal(L.filterSummary(hidden({ kind: 'patch' })), 'No class changes · Patches');
  assert.equal(L.filterSummary(hidden({ cats: [] })), 'No class changes · No categories');
  assert.equal(L.filterSummary(hidden({ cats: ['items'] }), L.availableCategories(data)), 'No class changes · Items');
});
